"use strict";
"use client";
'use strict';

var createContext = require('../../create-context.cjs');

const [CommandContextProvider, useCommandContext] = createContext.createContext({
  name: "CommandContext",
  hookName: "useCommandContext",
  providerName: "<Command.Root />"
});
const [CommandProviderContextProvider, useCommandProviderContext] = createContext.createContext({
  name: "CommandProviderContext",
  strict: false
});

exports.CommandContextProvider = CommandContextProvider;
exports.CommandProviderContextProvider = CommandProviderContextProvider;
exports.useCommandContext = useCommandContext;
exports.useCommandProviderContext = useCommandProviderContext;
